        content:
          '**차원 수는 로컬 RAG에서 가장 과도하게 설계된 선택입니다.** 더 많은 차원은 ~1,024까지 검색에 도움이 되다가 안정됩니다. 그 이상에서는 1%포인트 미만의 recall 향상을 위해 두 배의 저장 비용을 치릅니다.',
